using Alterverse.Visuals;using UnityEngine;
namespace Alterverse.Match
{
public sealed class DimensionsFrontVisual:MonoBehaviour
{
[SerializeField]private float arenaHalfWidth=39f,frontLength=68f,smoothing=6f,waveAmplitude=.8f,waveSpeed=1.15f;[SerializeField]private int segmentCount=25;private DimensionsFront front;private Transform[] segments,shards;private Renderer[] segmentRenderers,shardRenderers;private MaterialPropertyBlock block;private static readonly int BaseColorId=Shader.PropertyToID("_BaseColor"),ColorId=Shader.PropertyToID("_Color");private float targetX,impactZ,impactStrength,impactTime=-99;
private void Start(){front=FindAnyObjectByType<DimensionsFront>();block=new MaterialPropertyBlock();BuildFront();if(front!=null){targetX=ControlToX(front.LumenControl);front.ControlChanged+=OnControlChanged;}}
public void PulseImpact(float worldZ,int scoringTeam){impactZ=Mathf.Clamp(worldZ,-frontLength*.5f,frontLength*.5f);impactStrength=scoringTeam==1?-1:1;impactTime=Time.time;}
private void BuildFront(){segmentCount=Mathf.Max(9,segmentCount);segments=new Transform[segmentCount];segmentRenderers=new Renderer[segmentCount];shards=new Transform[segmentCount];shardRenderers=new Renderer[segmentCount];float step=frontLength/(segmentCount-1);for(int i=0;i<segmentCount;i++){float z=-frontLength*.5f+i*step;GameObject tear=Create("DF_RealityTear",PrimitiveType.Cube,new Vector3(0,.13f,z),new Vector3(.28f,.11f,step*1.12f));tear.transform.SetParent(transform,true);segments[i]=tear.transform;segmentRenderers[i]=tear.GetComponent<Renderer>();GameObject shard=Create("DF_FrontShard",PrimitiveType.Cube,new Vector3(0,.45f,z),new Vector3(.18f,.55f,.18f));shard.transform.SetParent(transform,true);shard.transform.rotation=Quaternion.Euler(18,i*47,25);shards[i]=shard.transform;shardRenderers[i]=shard.GetComponent<Renderer>();}}
private static GameObject Create(string n,PrimitiveType type,Vector3 p,Vector3 s){GameObject g=GameObject.CreatePrimitive(type);g.name=n;g.transform.position=p;g.transform.localScale=s;Collider c=g.GetComponent<Collider>();if(c!=null)c.enabled=false;return g;}
private void Update(){if(segments==null)return;float t=Time.time,control=front!=null?front.LumenControl:50,impactAge=t-impactTime,impactFade=impactAge>=0&&impactAge<1.8f?1-impactAge/1.8f:0;Color energy=Color.Lerp(StylizedArtDirection.ZeroEnergy,StylizedArtDirection.LumenEnergy,control/100);for(int i=0;i<segments.Length;i++){float wave=Mathf.Sin(t*waveSpeed+i*.72f)*waveAmplitude+Mathf.Sin(t*.63f+i*1.37f)*waveAmplitude*.32f,distance=Mathf.Abs(segments[i].position.z-impactZ),localImpact=impactFade*Mathf.Exp(-distance*.16f)*impactStrength*1.8f,desired=targetX+wave+localImpact;Transform s=segments[i];Vector3 p=s.position;p.x=Mathf.Lerp(p.x,desired,1-Mathf.Exp(-smoothing*Time.deltaTime));p.y=.12f+.03f*Mathf.Sin(t*4.5f+i*.8f);s.position=p;float pulse=.82f+Mathf.Sin(t*5+i*.55f)*.18f;s.localScale=new Vector3(.26f+pulse*.18f+Mathf.Abs(localImpact)*.06f,.07f+pulse*.06f,s.localScale.z);SetColor(segmentRenderers[i],Color.Lerp(energy,Color.white,.12f+Mathf.Abs(localImpact)*.16f));Transform shard=shards[i];Vector3 sp=shard.position;sp.x=p.x+(i%2==0?1:-1)*(.48f+.18f*Mathf.Sin(t+i));sp.y=.42f+.18f*Mathf.Sin(t*1.8f+i);shard.position=sp;shard.Rotate(35*Time.deltaTime,70*Time.deltaTime,22*Time.deltaTime,Space.Self);SetColor(shardRenderers[i],i%2==0?StylizedArtDirection.ZeroEnergy:StylizedArtDirection.LumenEnergy);}}
private void SetColor(Renderer r,Color c){if(r==null)return;block.Clear();block.SetColor(BaseColorId,c);block.SetColor(ColorId,c);r.SetPropertyBlock(block);}private void OnControlChanged(float zero,float lumen){targetX=ControlToX(lumen);}private float ControlToX(float lumen)=>Mathf.Lerp(arenaHalfWidth,-arenaHalfWidth,lumen/100);private void OnDestroy(){if(front!=null)front.ControlChanged-=OnControlChanged;}
}}
